// skill's prose author the Behavior's sources — and because derivation
// REPLACES, a compiled prompt with no chips silently erased every stored
// source, including the default `content` one (`lobu apply` resends `prompt`
// on every bump). Chip derivation stays a `create`-time affordance for the
// owletto composer, the one caller that still sends human-written prompt
// text; see `handleCreate`.
const sourcesProvided = args.sources !== undefined;
const storedSources = normalizeStoredJsonField(
  watcherRows[0].sources,
  [] as Array<{ name: string; query: string }>
);
const sources = sourcesProvided ? (args.sources ?? []) : storedSources;

