input.new_string:
// The assignment carries the per-assignment sources AND names the group whose
// root owns the version rows (see handleCreateVersion / handleGetVersions).
// Reading versions off `args.behavior_id` directly meant an assignment made
// by create_from_version could list a version via get_versions and then fail
// to fetch it here.
const watcherRows = await sql`
  SELECT id, watcher_group_id, sources
  FROM watchers WHERE id = ${args.behavior_id}
`;
if (watcherRows.length === 0) {
  throw new Error(`Behavior ${args.behavior_id} not found`);
}
const groupId = Number(watcherRows[0].watcher_group_id ?? watcherRows[0].id);

let rows;
if (args.version !== undefined) {
  rows = await sql`
    SELECT
      id, version, name, description, prompt,
      version_sources,
      keying_config, classifiers,
      reactions_guidance
    FROM watcher_versions
    WHERE watcher_id = ${groupId} AND version = ${args.version}
    LIMIT 1
  `;
} else {
  rows = await sql`
    SELECT
      v.id, v.version, v.name, v.description, v.prompt,
      v.version_sources,
      v.keying_config, v.classifiers,
      v.reactions_guidance
    FROM watcher_versions v
    JOIN watchers w ON v.id = w.current_version_id
    WHERE w.id = ${args.behavior_id}
    LIMIT 1
  `;
}

if (rows.length === 0) {
  throw new Error(
    `Version ${args.version ?? 'current'} not found for Behavior ${args.behavior_id}`
  );
}

const v = rows[0] as Record<string, unknown>;

// Sources are per-assignment and unversioned: `create_version` writes
// `version_sources` as NULL on purpose, so one assignment's list can't
// override its siblings'. Reporting that column alone made every v≥2 read
// back `sources: []` for a Behavior that plainly has sources. Fall through
// to the assignment's live list, matching get_content's preference order —
// these are the sources the Behavior actually runs with. Only the
// instruction text is frozen per version; sources are not.
const versionSources = normalizeStoredJsonField(
  v.version_sources,
  [] as Array<{ name: string; query: string }>
);

return {
  action: 'get_version_details',
  behavior_id: args.behavior_id,
  version_id: String(v.id),
  version: Number(v.version),
  name: v.name as string | undefined,
  description: v.description as string | undefined,
  prompt: v.prompt as string,
  sources:
    versionSources.length > 0
      ? versionSources
      : normalizeStoredJsonField(
          watcherRows[0].sources,
          [] as Array<{ name: string; query: string }>
        ),

