toolUseResult.originalFile:
/**
 * A Behavior's sources are Behavior-authored. Its instruction text is not an
 * input to them. Issue #2320 must-fix 2 (residual half).
 *
 * Since #2331 a Behavior's `prompt` column is no longer something a human
 * wrote — it is the COMPILED join of the skill bodies its `skills[]` named,
 * frozen at apply time. `create_version` was still re-deriving `sources[]`
 * from `@`-mention tokens in that text, which makes two things go wrong at
 * once:
 *
 *   - a skill body that happens to carry a chip-shaped token silently rewrites
 *     the Behavior's source list to whatever the skill mentions, and
 *   - because derivation REPLACES rather than merges, every stored source with
 *     no matching token in the new text is dropped — including the default
 *     `content` source every Behavior is created with. `lobu apply` resends
 *     `prompt` on each run, so a Behavior could lose its sources on a bump
 *     that changed nothing about them.
 *
 * `get_version_details` had the mirror-image problem: `version_sources` is
 * deliberately NULL on every row `create_version` writes (sources are
 * per-assignment now), so it reported `sources: []` for every v≥2 — a
 * Behavior that plainly has sources reads as sourceless. It also looked
 * versions up on the passed behavior id while `get_versions` resolves the
 * group ROOT, so an assignment made by `create_from_version` could list a
 * version it could not then fetch.
 */
import { beforeAll, describe, expect, it } from "vitest";
import type { Env } from "../../../index";
import type { AuthContext } from "../../../tools/execute";
import { executeTool } from "../../../tools/execute";
import { DEFAULT_BEHAVIOR_SOURCE_QUERY } from "../../../watchers/source-refs";
import { initWorkspaceProvider } from "../../../workspace";
import { cleanupTestDatabase, getTestDb } from "../../setup/test-db";
import {
	addUserToOrganization,
	createTestAgent,
	createTestOrganization,
	createTestUser,
} from "../../setup/test-fixtures";

const TEST_ENV: Env = {
	ENVIRONMENT: "test",
	DATABASE_URL: process.env.DATABASE_URL,
	JWT_SECRET: "test-jwt-secret-for-testing-only",
	BETTER_AUTH_SECRET: "test-auth-secret-for-testing-only",
	MAX_CONSECUTIVE_FAILURES: "3",
	RATE_LIMIT_ENABLED: "false",
};

/**
 * A compiled skill body that mentions a source the way the owletto composer
 * serialises one. Nothing about it is Behavior authoring — it is prose that
 * happens to match the chip codec.
 */
const SKILL_BODY_WITH_CHIP = [
	"# Daily digest",
	"",
	"Summarise overnight activity. Pull the numbers from",
	"@[sql:skill_pull:Skill Pull](#sql=SELECT%20id%20FROM%20events) before writing.",
].join("\n");

/** A Behavior-authored source. Queries must project `id` — see shared.ts. */
const RECENT_QUERY = "SELECT id FROM events ORDER BY occurred_at DESC";

type Sources = Array<{ name: string; query: string }>;

describe("manage_behaviors — instruction text never authors sources", () => {
	let orgId: string;
	let ownerCtx: AuthContext;
	let agentId: string;
	let behaviorId: string;

	const baseCtx = (orgIdValue: string, userId: string): AuthContext => ({
		organizationId: orgIdValue,
		tokenOrganizationId: orgIdValue,
		userId,
		memberRole: "owner",
		agentId: null,
		requestedAgentId: null,
		isAuthenticated: true,
		clientId: null,
		scopes: ["mcp:read", "mcp:write", "mcp:admin"],
		tokenType: "oauth",
		requestUrl: `http://localhost/api/${orgIdValue}`,
		baseUrl: "",
		scopedToOrg: true,
		allowCrossOrg: false,
	});

	async function storedSources(id = behaviorId): Promise<Sources> {
		const sql = getTestDb();
		const rows = await sql`SELECT sources FROM watchers WHERE id = ${id}`;
		return ((rows[0] as { sources: Sources | null }).sources ?? []) as Sources;
	}

	async function createVersion(
		args: Record<string, unknown>
	): Promise<{ version?: number }> {
		return (await executeTool(
			"manage_behaviors",
			{ action: "create_version", behavior_id: behaviorId, ...args },
			TEST_ENV,
			ownerCtx
		)) as { version?: number };
	}

	beforeAll(async () => {
		await cleanupTestDatabase();
		await initWorkspaceProvider();

		const org = await createTestOrganization({ name: "behavior source honesty" });
		orgId = org.id;
		const owner = await createTestUser({ email: "bsh-owner@test.com" });
		await addUserToOrganization(owner.id, org.id, "owner");
		ownerCtx = baseCtx(org.id, owner.id);

		const agent = await createTestAgent({
			organizationId: org.id,
			agentId: "bsh-agent",
			ownerUserId: owner.id,
		});
		agentId = agent.agentId;

		const created = (await executeTool(
			"manage_behaviors",
			{
				action: "create",
				slug: "bsh-digest",
				name: "Digest",
				prompt: "Write the digest.",
				agent_id: agentId,
			},
			TEST_ENV,
			ownerCtx
		)) as { behavior_id?: string };
		behaviorId = created.behavior_id!;
	});

	it("starts with the default content source", async () => {
		expect(await storedSources()).toEqual([
			{ name: "content", query: DEFAULT_BEHAVIOR_SOURCE_QUERY },
		]);
	});

	it("a compiled skill body's chip does not rewrite the Behavior's sources", async () => {
		await createVersion({ prompt: SKILL_BODY_WITH_CHIP });

		// The skill mentioned a query. It is still the skill's prose, not the
		// Behavior's source list.
		expect(await storedSources()).toEqual([
			{ name: "content", query: DEFAULT_BEHAVIOR_SOURCE_QUERY },
		]);
	});

	it("a prompt-only bump keeps the stored sources", async () => {
		await createVersion({ prompt: "Write the digest, briefly." });

		expect(await storedSources()).toEqual([
			{ name: "content", query: DEFAULT_BEHAVIOR_SOURCE_QUERY },
		]);
	});

	it("explicit sources replace, and an explicit empty list clears (#2048)", async () => {
		await createVersion({
			prompt: SKILL_BODY_WITH_CHIP,
			sources: [{ name: "recent", query: RECENT_QUERY }],
		});
		expect(await storedSources()).toEqual([
			{ name: "recent", query: RECENT_QUERY },
		]);

		await createVersion({ sources: [] });
		expect(await storedSources()).toEqual([]);

		// Restore a source for the reporting assertions below.
		await createVersion({
			sources: [{ name: "recent", query: RECENT_QUERY }],
		});
		expect(await storedSources()).toEqual([
			{ name: "recent", query: RECENT_QUERY },
		]);
	});

	it("get_version_details reports the sources the Behavior actually runs with", async () => {
		const details = (await executeTool(
			"manage_behaviors",
			{ action: "get_version_details", behavior_id: behaviorId },
			TEST_ENV,
			ownerCtx
		)) as { version: number; sources: Sources };

		// Several versions deep — `version_sources` is NULL on every one of them.
		expect(details.version).toBeGreaterThan(1);
		expect(details.sources).toEqual([
			{ name: "recent", query: RECENT_QUERY },
		]);
	});

	it("get_version_details can fetch any version get_versions listed", async () => {
		const listed = (await executeTool(
			"manage_behaviors",
			{ action: "get_versions", behavior_id: behaviorId },
			TEST_ENV,
			ownerCtx
		)) as { versions: Array<{ version: number }> };

		for (const { version } of listed.versions) {
			const details = (await executeTool(
				"manage_behaviors",
				{ action: "get_version_details", behavior_id: behaviorId, version },
				TEST_ENV,
				ownerCtx
			)) as { version: number };
			expect(details.version).toBe(version);
		}
	});
});

