+	connector: "connector",
+	channel: "channel",
+	metric: "metric",
+};
+
+function sourceName(value: string): string {
+	return (
+		value
+			.trim()
+			.toLowerCase()
+			.replace(/[^a-z0-9_]+/g, "_")
+			.replace(/^_+|_+$/g, "") || "source"
