import { createFileRoute } from "@tanstack/react-router";
import { BehaviorsNew } from "@/components/agents/behaviors/behaviors-new";
import { pruneSearch } from "@/lib/router-search";

// Search params carried by a Slack channel notice. They prefill the same
// canonical Behavior event editor used everywhere else; there is no separate
// Behavior-subscription UI path. All fields are optional for ordinary creation.
export type PrefilledChannel = {
	listen?: string;
	platform?: string;
	team?: string;
	label?: string;
	connection?: string;
	resource_type?: string;
	resource?: string;
	events?: string;
};

export const Route = createFileRoute("/$owner/agents/$agentId/behaviors/new")({
	component: AgentBehaviorsNewPage,
	// `pruneSearch` strips undefined keys — without it TSR's URL stringifier and
	// validateSearch disagree on shape, causing a commit loop on mount.
	validateSearch: (search: Record<string, unknown>): PrefilledChannel =>
		pruneSearch({
			listen: typeof search.listen === "string" ? search.listen : undefined,
			platform:
				typeof search.platform === "string" ? search.platform : undefined,
			team: typeof search.team === "string" ? search.team : undefined,
			label: typeof search.label === "string" ? search.label : undefined,
			connection:
				typeof search.connection === "string" ? search.connection : undefined,
			resource_type:
				typeof search.resource_type === "string"
					? search.resource_type
					: undefined,
			resource:
				typeof search.resource === "string" ? search.resource : undefined,
			events: typeof search.events === "string" ? search.events : undefined,
		}),
});

function AgentBehaviorsNewPage() {
	const { owner, agentId } = Route.useParams();
	const prefilled = Route.useSearch();
	return <BehaviorsNew owner={owner} agentId={agentId} prefilled={prefilled} />;
}

