import type { ReactNode } from "react";
import { useState } from "react";
import {
	Command,
	CommandEmpty,
	CommandGroup,
	CommandInput,
	CommandList,
} from "@/components/ui/command";
import {
	Popover,
	PopoverContent,
	PopoverTrigger,
} from "@/components/ui/popover";
import { cn } from "@/lib/utils";

/**
 * Shell for the Popover + Command "search-select" pattern that was hand-rolled
 * across the entity / connector / member selectors. It owns the open state and
 * the Popover/Command/CommandInput/List/Empty/Group scaffolding; callers supply
 * the trigger and the `CommandItem`s, so item rendering and selection UI (Check
 * vs Checkbox, custom rows) stay with the caller.
 *
 * `trigger` receives the open state (for `aria-expanded` / chevron rotation).
 * `children` receives a `close` callback and the current search `query`: single-
 * select callers call `close` after applying the selection; multi-select callers
 * ignore it so the popover stays open. The `query` lets callers offer a
 * "create <query>" row for values that aren't in the list.
 */
export function Combobox({
	trigger,
	searchPlaceholder,
	emptyText,
	contentClassName,
	align = "start",
	children,
}: {
	trigger: (open: boolean) => ReactNode;
	searchPlaceholder: string;
	emptyText: ReactNode;
	contentClassName?: string;
	align?: "start" | "center" | "end";
	children: (close: () => void, query: string) => ReactNode;
}) {
	const [open, setOpen] = useState(false);
	const [query, setQuery] = useState("");
	return (
		<Popover
			open={open}
			onOpenChange={(next) => {
				setOpen(next);
				if (!next) setQuery("");
			}}
		>
			<PopoverTrigger asChild>{trigger(open)}</PopoverTrigger>
			<PopoverContent className={cn("p-0", contentClassName)} align={align}>
				<Command>
					<CommandInput
						placeholder={searchPlaceholder}
						value={query}
						onValueChange={setQuery}
					/>
					<CommandList>
						<CommandEmpty>{emptyText}</CommandEmpty>
						<CommandGroup>
							{children(() => {
								setOpen(false);
								setQuery("");
							}, query)}
						</CommandGroup>
					</CommandList>
				</Command>
			</PopoverContent>
		</Popover>
	);
}

