30	/**
31	 * The Behavior's data sources, authored on their own.
32	 *
33	 * Sources used to be a side effect of `@`-chips in the goal field. #2320 takes
34	 * the goal away (instructions are compiled skills now), and sources stay
35	 * Behavior-owned — skills never author them — so they need a surface of their
36	 * own rather than disappearing with the prompt.
37	 */
38	export function BehaviorSourcesEditor({
39		sources,
40		onChange,
41		disabled,
42	}: {
43		sources: BehaviorSource[];
44		onChange: (next: BehaviorSource[]) => void;
45		disabled?: boolean;
46	}) {
47		const { currentOwner, resolvedOrganizationId } = useOrgContext();
48		const [query, setQuery] = useState("");
49		const [sqlOpen, setSqlOpen] = useState(false);
50	
51		const { refs } = useReferenceSearch({
52			owner: currentOwner,
53			organizationId: resolvedOrganizationId,
54			kinds: SOURCE_KINDS,
55			query,
56			limitPerKind: 10,
57		});
58	
59		const addSql = (value: SqlSourceValue) => {
60			onChange(
61				behaviorSourcesWithRef(
62					{
63						kind: "sql",
64						id: "",
65						label: value.name,
66						path: sqlRefPath(value.query),
67					},
68					sources,
69				),
70			);
71		};
72	
73		return (
74			<div className="space-y-2">
75				<Label>Sources</Label>
76	
77				{sources.length > 0 ? (
78					<ul className="space-y-2">
79						{sources.map((source) => (
80							<li
81								key={source.query}
82								className="flex items-start gap-2 rounded-lg border bg-background p-2"
83							>
84								<div className="min-w-0 flex-1">
85									<div className="truncate font-mono text-xs font-medium">
86										{source.name}
87									</div>
88									<div className="truncate text-xs text-muted-foreground">
89										{source.query}
90									</div>
91								</div>
92								<Button
93									type="button"
94									variant="ghost"
95									size="icon"
96									className="h-7 w-7 shrink-0"
97									aria-label={`Remove source ${source.name}`}
98									disabled={disabled}
99									onClick={() =>
100										onChange(sources.filter((s) => s.query !== source.query))
101									}
102								>
103									<X className="h-3.5 w-3.5" />
104								</Button>
105							</li>
106						))}
107					</ul>
108				) : null}
109	
110				<div className="flex gap-2">
111					<Combobox
112						searchPlaceholder="Search feeds, connections, metrics…"
113						emptyText="No matching reference."
114						onQueryChange={setQuery}
115						trigger={() => (
116							<Button
117								type="button"
118								variant="outline"
119								size="sm"
120								disabled={disabled}
121							>
122								<Plus className="mr-2 h-3.5 w-3.5" />
123								Add source
124							</Button>
125						)}
126					>
127						{(close) =>
128							refs.map((ref) => (
129								<CommandItem
130									key={`${ref.kind}:${ref.id}`}
131									value={`${ref.label} ${ref.kind}`}
132									onSelect={() => {
133										onChange(behaviorSourcesWithRef(ref, sources));
134										close();
135									}}
136								>
137									<span className="truncate text-sm">{ref.label}</span>
138									<span className="ml-2 shrink-0 text-xs text-muted-foreground">
139										{ref.kind}
140									</span>
141								</CommandItem>
142							))
143						}
144					</Combobox>
145	
146					<Button
147						type="button"
148						variant="outline"
149						size="sm"
150						disabled={disabled}
151						onClick={() => setSqlOpen(true)}
152					>
153						<Code2 className="mr-2 h-3.5 w-3.5" />
154						Add SQL
155					</Button>
156				</div>
157	
158				<p className="text-xs text-muted-foreground">
159					Data handed to the agent alongside its instructions. Behavior-owned —
160					skills never add or remove sources.
161				</p>
162	
163				<SqlSourceDialog
164					open={sqlOpen}
165					onOpenChange={setSqlOpen}
166					onSubmit={addSql}
167				/>
