type CatalogPrefill = NonNullable<CreateWatcherFormProps["catalogPrefill"]>;

function templateToPrefill(template: BehaviorCatalogTemplate): CatalogPrefill {
	catalogPrefill,
	onDraft,
	triggerFields,
	submitLabel,
	submitDisabled,
	suggestedPrompt,
	createFields,
}: CreateWatcherFormProps) {
	const createWatcher = useCreateWatcher();
	const createVersion = useCreateWatcherVersion();
	const setReactionScript = useSetReactionScript();

	const handleCreate = async (params: WatcherFormDraft) => {
		try {
			if (onDraft) {
				await onDraft(params);
				return;
			}
			if (isEditing) {
				const triggers =
					createFields?.triggers ?? editingWatcher.triggers ?? [];
				// Single atomic create_version call — also updates Behavior-level fields.
				await createVersion.mutateAsync({
					behavior_id: editingWatcher.behavior_id,
					name: params.name,
					description: params.description,
					prompt: params.prompt,
					sources: params.sources,
					set_as_current: true,
					triggers,
					scheduler_client_id: params.scheduler_client_id || null,
					classifiers: params.classifiers,
						behavior_id: editingWatcher.behavior_id,
						...watcherUpdates,
					});
				}
				handleClose();
				onSuccess?.(editingWatcher.behavior_id);
			} else {
				const initialTriggers =
					createFields?.triggers ??
					templatePrefill?.triggers ??
					catalogPrefill?.triggers ??
					[];
				const result = await createWatcher.mutateAsync({
					...params,
					triggers: initialTriggers,
				});
				handleClose();
				if (result.behavior_id) {
					onSuccess?.(result.behavior_id);
				}
			}
						<FormFooter onCancel={handleClose} />
					) : null}
				</>
			) : (
				<FromScratchPanel
					organizationId={organizationId}
					entityId={entityId}
					prefill={
						editPrefill ??
						clonePrefill ??
						templatePrefill ??
						catalogPrefill ??
						agentPrefill
					}
					onSubmit={handleCreate}
