// @vitest-environment jsdom
import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import {
	fireEvent,
	render as rtlRender,
	screen,
	waitFor,
} from "@testing-library/react";
import type { ReactElement } from "react";
import { describe, expect, it, vi } from "vitest";

function render(ui: ReactElement) {
	const client = new QueryClient({
		defaultOptions: { queries: { retry: false } },
	});
	const wrap = (node: ReactElement) => (
		<QueryClientProvider client={client}>{node}</QueryClientProvider>
	);
	const result = rtlRender(wrap(ui));
	return {
		...result,
		rerender: (node: ReactElement) => result.rerender(wrap(node)),
	};
}

// The real editor is a controlled ProseMirror MentionEditor whose setContent
// (used to reflect a programmatic value change) ECHOES an onChange with the new
// value. A plain controlled <textarea> does not echo, so mimic the echo here —
// otherwise this mock hides the "seed trips the edited flag" class of bug.
vi.mock("./template-fields-editor", () => {
	const { useEffect, useRef } = require("react") as typeof import("react");
	return {
		TemplateFieldsEditor: ({
			prompt,
			onPromptChange,
		}: {
			prompt: string;
			onPromptChange: (value: string) => void;
		}) => {
			const last = useRef(prompt);
			useEffect(() => {
				if (last.current !== prompt) {
					last.current = prompt;
					// Echo the programmatic value back, exactly like MentionEditor.
					onPromptChange(prompt);
				}
			}, [prompt, onPromptChange]);
			return (
				<textarea
					aria-label="Goal"
					value={prompt}
					onChange={(e) => {
						last.current = e.target.value;
						onPromptChange(e.target.value);
					}}
				/>
			);
		},
	};
});

vi.mock("@/components/ui/code-editor", () => ({
	CodeEditor: () => null,
}));

vi.mock("@/hooks/use-features", () => ({
	useFeatures: () => ({ lobuEmbedded: false }),
}));
vi.mock("@/lib/api/agents", () => ({ useAgents: () => ({ data: [] }) }));
vi.mock("@/lib/api", () => ({
	useConnectedClients: () => ({ data: [] }),
	useEntities: () => ({ data: [] }),
}));
vi.mock("@/lib/api/entities", () => ({ useEntityTypes: () => ({ data: [] }) }));

import { FromScratchPanel } from "./from-scratch-panel";

const baseProps = {
	organizationId: "org-1",
	onSubmit: vi.fn(),
	isSubmitting: false,
	error: null,
};

describe("FromScratchPanel layout", () => {
	it("renders Name, then Goal, then the trigger fields in order", () => {
		render(
			<FromScratchPanel
				{...baseProps}
				triggerFields={<div data-testid="trigger-fields">trigger</div>}
			/>,
		);

		const name = screen.getByPlaceholderText("e.g., Escalation signals");
		const goal = screen.getByLabelText("Goal");
		const trigger = screen.getByTestId("trigger-fields");

		// Node.compareDocumentPosition: FOLLOWING (4) means the argument comes
		// after the reference node in document order.
		expect(
			name.compareDocumentPosition(goal) &
				Node.DOCUMENT_POSITION_FOLLOWING,
		).toBeTruthy();
		expect(
			goal.compareDocumentPosition(trigger) &
				Node.DOCUMENT_POSITION_FOLLOWING,
		).toBeTruthy();
	});
});

describe("FromScratchPanel prompt seeding", () => {
	it("seeds the empty prompt from the trigger suggestion and enables submit", async () => {
		const onSubmit = vi.fn();
		render(
			<FromScratchPanel
				{...baseProps}
				onSubmit={onSubmit}
				suggestedPrompt="When a message is sent, respond appropriately."
			/>,
		);

		const prompt = screen.getByLabelText("Goal") as HTMLTextAreaElement;
		await waitFor(() =>
			expect(prompt.value).toBe(
				"When a message is sent, respond appropriately.",
			),
		);

		fireEvent.change(screen.getByPlaceholderText("e.g., Escalation signals"), {
			target: { value: "Triage" },
		});
		fireEvent.click(screen.getByRole("button", { name: "Create Behavior" }));
		expect(onSubmit).toHaveBeenCalledWith(
			expect.objectContaining({
				prompt: "When a message is sent, respond appropriately.",
			}),
		);
	});

	it("does not overwrite a prompt the author has edited", async () => {
		const { rerender } = render(
			<FromScratchPanel {...baseProps} suggestedPrompt="First suggestion." />,
		);
		const prompt = screen.getByLabelText("Goal") as HTMLTextAreaElement;
		await waitFor(() => expect(prompt.value).toBe("First suggestion."));

		rerender(
			<FromScratchPanel {...baseProps} suggestedPrompt="Second suggestion." />,
		);
		await waitFor(() => expect(prompt.value).toBe("Second suggestion."));

		fireEvent.change(prompt, { target: { value: "My own instructions" } });
		rerender(
			<FromScratchPanel {...baseProps} suggestedPrompt="Third suggestion." />,
		);
		expect(prompt.value).toBe("My own instructions");
	});

	it("allows the author to clear a suggested prompt", async () => {
		render(
			<FromScratchPanel {...baseProps} suggestedPrompt="First suggestion." />,
		);
		const prompt = screen.getByLabelText("Goal") as HTMLTextAreaElement;
		await waitFor(() => expect(prompt.value).toBe("First suggestion."));

		fireEvent.change(prompt, { target: { value: "" } });

		await waitFor(() => expect(prompt.value).toBe(""));
	});

	it("clears an untouched suggestion when the trigger has none", async () => {
		const { rerender } = render(
			<FromScratchPanel {...baseProps} suggestedPrompt="First suggestion." />,
		);
		const prompt = screen.getByLabelText("Goal") as HTMLTextAreaElement;
		await waitFor(() => expect(prompt.value).toBe("First suggestion."));

		rerender(<FromScratchPanel {...baseProps} />);

		await waitFor(() => expect(prompt.value).toBe(""));
	});

	it("re-seeds after the editor echoes the seed (does not self-freeze)", async () => {
		// Regression: MentionEditor echoes onChange after a programmatic seed. If
		// that echo is mistaken for an author edit, seeding freezes and later
		// trigger changes stop updating the untouched prompt. The echo mock above
		// reproduces it; before the fix, "Second suggestion." never landed.
		const { rerender } = render(
			<FromScratchPanel {...baseProps} suggestedPrompt="First suggestion." />,
		);
		const prompt = screen.getByLabelText("Goal") as HTMLTextAreaElement;
		await waitFor(() => expect(prompt.value).toBe("First suggestion."));

		rerender(
			<FromScratchPanel {...baseProps} suggestedPrompt="Second suggestion." />,
		);
		await waitFor(() => expect(prompt.value).toBe("Second suggestion."));
	});

	it("never overwrites a template/clone prefill prompt", async () => {
		render(
			<FromScratchPanel
				{...baseProps}
				prefill={{ name: "Tmpl", prompt: "Curated template prompt." }}
				suggestedPrompt="Trigger suggestion."
			/>,
		);
		const prompt = screen.getByLabelText("Goal") as HTMLTextAreaElement;
		await waitFor(() => expect(prompt.value).toBe("Curated template prompt."));
	});
});

describe("FromScratchPanel source edits", () => {
	const oldQuery = "SELECT id FROM events WHERE payload_type = 'old'";
	const newQuery = "SELECT id FROM events WHERE payload_type = 'new'";
	const oldChip = `@[sql:recent:Recent](#sql=${encodeURIComponent(oldQuery)})`;
	const newChip = `@[sql:recent:Recent](#sql=${encodeURIComponent(newQuery)})`;

	it("preserves stored sources when only instruction text changes", () => {
		const onSubmit = vi.fn();
		render(
			<FromScratchPanel
				{...baseProps}
				isEditing
				onSubmit={onSubmit}
				prefill={{
					name: "Digest",
					prompt: `Watch ${oldChip}.`,
					sources: [{ name: "recent", query: oldQuery }],
				}}
			/>,
		);

		fireEvent.change(screen.getByLabelText("Goal"), {
			target: { value: `Briefly watch ${oldChip}.` },
		});
		fireEvent.click(screen.getByRole("button", { name: "Save Behavior" }));

		expect(onSubmit).toHaveBeenCalledWith(
			expect.objectContaining({ sources: undefined }),
		);
	});

	it("sends an explicit replacement when a source chip changes", () => {
		const onSubmit = vi.fn();
		render(
			<FromScratchPanel
				{...baseProps}
				isEditing
				onSubmit={onSubmit}
				prefill={{
					name: "Digest",
					prompt: `Watch ${oldChip}.`,
					sources: [
						{ name: "recent", query: oldQuery },
						{ name: "curated", query: "@feed:curated" },
					],
				}}
			/>,
		);

		fireEvent.change(screen.getByLabelText("Goal"), {
			target: { value: `Watch ${newChip}.` },
		});
		fireEvent.click(screen.getByRole("button", { name: "Save Behavior" }));

		expect(onSubmit).toHaveBeenCalledWith(
			expect.objectContaining({
				sources: [
					{ name: "curated", query: "@feed:curated" },
					{ name: "recent", query: newQuery },
				],
			}),
		);
	});

	it("sends an explicit empty list when the last source chip is removed", () => {
		const onSubmit = vi.fn();
		render(
			<FromScratchPanel
				{...baseProps}
				isEditing
				onSubmit={onSubmit}
				prefill={{
					name: "Digest",
					prompt: `Watch ${oldChip}.`,
					sources: [{ name: "recent", query: oldQuery }],
				}}
			/>,
		);

		fireEvent.change(screen.getByLabelText("Goal"), {
			target: { value: "Watch recent activity." },
		});
		fireEvent.click(screen.getByRole("button", { name: "Save Behavior" }));

		expect(onSubmit).toHaveBeenCalledWith(
			expect.objectContaining({ sources: [] }),
		);
	});
});

