export default async (ctx, client) => {
  // Agents with a skills library, and their Behaviors' trigger shapes — the
  // inputs to the #2320 rules we just implemented in the web form.
  const agents = await client.agents.list();
  const arr = Array.isArray(agents) ? agents : (agents.agents ?? agents.items ?? []);
  return arr.slice(0, 12).map((a) => ({ id: a.agent_id ?? a.id, name: a.name }));
}

