export default async (ctx, client) => {
  const rows = await client.query_sql({
    query: `SELECT w.id, w.slug, w.name, wv.version, wv.prompt
            FROM watchers w
            JOIN watcher_versions wv ON wv.watcher_group_id = COALESCE(w.watcher_group_id, w.id)
            WHERE w.slug = 'zz-verify-compile'
            ORDER BY wv.version DESC LIMIT 3`,
  });
  return rows;
}

