export default async (ctx, client) => {
  // #2345 in prod: instruction text must not author sources on create_version.
  const created = await client.behaviors.create({
    slug: "zz-verify-source-honesty",
    name: "ZZ Verify Source Honesty",
    agent_id: "lobu-builder",
    prompt: "Initial instructions.",
    sources: [{ name: "alpha", query: "SELECT id FROM events LIMIT 1" }],
    triggers: [],
  });
  const id = created?.behavior_id ?? created?.id;
  const before = await client.behaviors.getVersionDetails
    ? await client.behaviors.getVersionDetails({ behavior_id: id })
    : null;
  return { id, created: Object.keys(created ?? {}), before };
}

export default async (ctx, client) => {
  // Bump the version with a chip-shaped prompt and NO `sources`. Pre-#2345 the
  // server re-derived sources from the prompt tokens and would have replaced
  // "alpha" with a chip-derived source. It must now inherit unchanged.
  await client.behaviors.createVersion({
    behavior_id: "67",
    prompt:
      "Compiled skill body mentioning @[sql:skill_pull:Skill Pull](#sql=SELECT%20id%20FROM%20events) inline.",
    set_as_current: true,
  });
  const after = await client.behaviors.getVersionDetails({ behavior_id: "67" });
  return { version: after.version, sources: after.sources, prompt: after.prompt?.slice(0, 60) };
}

export default async (ctx, client) => {
  // Explicit [] must still clear — omission inherits, passing is a full replace.
  await client.behaviors.createVersion({
    behavior_id: "67", prompt: "Third.", sources: [], set_as_current: true,
  });
  const cleared = await client.behaviors.getVersionDetails({ behavior_id: "67" });
  const out = { version: cleared.version, sources: cleared.sources };
  const del = await client.behaviors.delete({ behavior_ids: [67] });
  return { ...out, cleanup: del?.summary ?? del };
}

export default async (ctx, client) => {
  const rows = await client.query_sql
    ? null
    : null;
  const agents = await client.agents.list();
  const arr = Array.isArray(agents) ? agents : (agents.agents ?? agents.items ?? []);
  const out = [];
  for (const a of arr) {
    const id = a.agent_id ?? a.id;
    const d = await client.agents.get({ agent_id: id }).catch(() => null);
    out.push({ id, model: d?.model ?? a.model, providers: d?.installed_providers ?? a.installed_providers });
  }
  return out;
}

