	message: string
): Promise<boolean> {
	return sql.begin(async (tx) => {
		const [failed] = await tx<{
			watcher_id: string | number | null;
			dispatch_source: string | null;
		}>`
      UPDATE runs
      SET status = 'failed',
          completed_at = current_timestamp,
          error_message = ${message}
      WHERE id = ${runId}
        AND status = ANY(${runStatusLiteral(ACTIVE_RUN_STATUSES)}::text[])
      RETURNING watcher_id, approved_input->>'dispatch_source' AS dispatch_source
    `;
		if (!failed) return false;
		await advanceScheduleAfterTerminalFailure(
			tx,
			failed.watcher_id == null ? null : Number(failed.watcher_id),
			failed.dispatch_source
		);
		return true;
	});
}

/**
 * Reset a watcher run that missed `complete_window` back to `pending` so the
 * automation dispatch loop (`dispatchPendingWatcherRuns` → `claimWatcherRun`)
 * re-dispatches it for one more agent turn. Mirrors `resetOrphanedWatcherRuns`
 * (the proven re-dispatch shape) and records the attempt in
 * `approved_input.finalize_nudge_count` so it is strictly bounded. Status-
 * guarded so it can't resurrect an already-terminal run (replica-safe).
 */
async function requeueWatcherRunForFinalizeNudge(
	sql: DbClient,
	runId: number,
	nextNudgeCount: number
): Promise<void> {
	await sql`
    UPDATE runs
    SET status = 'pending',
        claimed_by = NULL,
        claimed_at = NULL,
        dispatched_message_id = NULL,
        error_message = NULL,
        approved_input = jsonb_set(
          COALESCE(approved_input, '{}'::jsonb),
          '{finalize_nudge_count}',
          to_jsonb(${nextNudgeCount}::int)
        )
    WHERE id = ${runId}
      AND status = ANY(${runStatusLiteral(ACTIVE_RUN_STATUSES)}::text[])
  `;
}

export async function resolveWatcherRunsByMessageIds(
	messageIds: Iterable<string>,
	result: WatcherTerminalResult,
	db?: DbClient
): Promise<{ resolved: number }> {
	const ids = Array.from(new Set(Array.from(messageIds).filter(Boolean)));
	if (ids.length === 0) return { resolved: 0 };

	const sql = db ?? getDb();
	const rows = await sql`
    SELECT r.id, r.approved_input, w.execution_config
    FROM runs r
    LEFT JOIN watchers w ON w.id = r.watcher_id
    WHERE r.run_type = 'behavior'
      AND r.dispatched_message_id = ANY(${pgTextArray(ids)}::text[])
      AND r.status = ANY(${runStatusLiteral(ACTIVE_RUN_STATUSES)}::text[])
  `;

	let resolved = 0;
	for (const row of rows) {
		const typedRow = row as {
			id: unknown;
			approved_input: Record<string, unknown> | null;
			execution_config: Record<string, unknown> | null;
		};
		const runId = Number(typedRow.id);
		if (!Number.isFinite(runId)) continue;

		if (!result.ok) {
			if (await markWatcherRunFailed(sql, runId, result.error)) resolved++;
			continue;
		}

		if (typedRow.approved_input?.trigger_execution === "turn") {
			await markWatcherRunCompleted(sql, runId, null);
			resolved++;
			continue;
		}

		const windowId = await findWindowIdForRun(sql, runId);
		if (windowId === null) {
			// The agent replied but never called complete_window — a soft, usually
			// non-deterministic miss. Re-dispatch for one more turn (bounded by
			// finalize_nudge_count) before giving up. The budget is per-watcher
			// (execution_config.finalize_nudges) with a global fallback.
			const budget = resolveFinalizeNudgeBudget(typedRow.execution_config);
			const nudgeCount = Number(
				typedRow.approved_input?.finalize_nudge_count ?? 0
			);
			if (Number.isFinite(nudgeCount) && nudgeCount < budget) {
				await requeueWatcherRunForFinalizeNudge(sql, runId, nudgeCount + 1);
				logger.info(
					{ run_id: runId, attempt: nudgeCount + 1, max: budget },
					"[watchers] Agent finished without complete_window — re-dispatching for finalize nudge"
				);
				resolved++;
				continue;
			}

			if (
				await markWatcherRunFailed(
					sql,
					runId,
					await describeFinalizeMiss(sql, runId, budget)
				)
			) {
				resolved++;
			}
			continue;
		}

		await markWatcherRunCompleted(sql, runId, windowId);
		resolved++;
	}

	return { resolved };
}

async function describeFinalizeMiss(
	sql: DbClient,
	runId: number,
	budget: number
): Promise<string> {
	const attempts = budget > 0 ? ` after ${budget + 1} attempt(s)` : "";
	const agentMiss =
		"Agent reply finished without calling run_sdk (client.behaviors.completeWindow)" +
		attempts;
	let pending: Array<{ mcpId: string; toolName: string }>;
	try {
		pending = await listPendingToolsForRun(runId, sql);
	} catch (error) {
		logger.warn(
			{ error, run_id: runId },
			"[watchers] Could not check pending tool approvals for a finalize miss"
		);
		return (
			agentMiss +
			". Tool approval status could not be checked; inspect the warning log " +
			"before attributing the miss to the agent."
		);
	}

	if (pending.length > 0) {
		const tools = pending.map((p) => `${p.mcpId}/${p.toolName}`).join(", ");
		const grants = pending
			.map((p) => `/mcp/${p.mcpId}/tools/${p.toolName}`)
			.join(", ");
		return (
			`Behavior run blocked on tool approval${attempts}: ${tools} queued for ` +
			"human approval, so complete_window never ran. Headless Behavior runs " +
			`cannot answer approval cards; grant standing access (${grants}) and ` +
			"retry the Behavior."
		);
	}

	return (
		agentMiss +
		". No active tool approval was found, so check that the assigned agent has the " +
		"lobu-memory MCP attached and that query_sdk / run_sdk are available to it."
	);
}

import { describe, expect, it } from "vitest";
import { resolveWatcherRunsByMessageIds } from "../../../watchers/run-completion";
import { getTestDb } from "../../setup/test-db";
import { createTestAgent, createTestEntity } from "../../setup/test-fixtures";
import { TestWorkspace } from "../../setup/test-mcp-client";

/**
 * `complete_window` defaults `runs.model_used` to the literal 'external-client'
 * whenever its caller omits `model`, and the platform's own Lobu agent omits it.
 * That left every server-dispatched Behavior run labelled as though an outside
 * MCP client had executed it — a label that reads as an observation and is not.
 * Triage of the July 2026 Behavior collapse drew exactly that wrong conclusion
 * from this column, so it is worth pinning.
 */
async function createDispatchedRun(opts: {
	slug: string;
	messageId: string;
	/** Seed `model_used` as `complete_window` would have left it. */
	modelUsed: string | null;
	triggerExecution?: "turn" | "window";
}) {
	const sql = getTestDb();
	const workspace = await TestWorkspace.create({
		name: `Run Provenance ${opts.slug}`,
	});
	const entity = await createTestEntity({
		name: "Provenance Entity",
		organization_id: workspace.org.id,
		created_by: workspace.users.owner.id,
	});
	const agent = await createTestAgent({
		organizationId: workspace.org.id,
		ownerUserId: workspace.users.owner.id,
		agentId: `provenance-agent-${opts.slug}`,
		name: "Provenance Agent",
	});

	const behavior = (await workspace.owner.behaviors.create({
		entity_id: entity.id,
		slug: opts.slug,
		name: "Provenance Behavior",
		prompt: "Summarize content.",
		triggers: [
			{
				kind: "schedule",
				cron: "0 * * * *",
				execution: "window",
				active_run: "coalesce",
				skip_if_unchanged: false,
			},
		],
		agent_id: agent.agentId,
	})) as { behavior_id: string };

	const [run] = await sql`
    INSERT INTO runs (organization_id, run_type, watcher_id, status,
                      dispatched_message_id, model_used, approved_input)
    VALUES (${workspace.org.id}, 'behavior', ${Number(behavior.behavior_id)},
            'running', ${opts.messageId}, ${opts.modelUsed},
            ${sql.json({
							dispatch_source: "scheduled",
							trigger_execution: opts.triggerExecution ?? "turn",
						})})
    RETURNING id
  `;

	return { sql, runId: Number(run.id) };
}

async function modelUsedOf(runId: number): Promise<string | null> {
	const sql = getTestDb();
	const [row] = await sql`SELECT model_used FROM runs WHERE id = ${runId}`;
	return (row?.model_used as string | null) ?? null;
}

describe("a completed Behavior run records who executed it", () => {
	it("replaces the 'external-client' placeholder with the real executor", async () => {
		const { runId } = await createDispatchedRun({
			slug: "provenance-placeholder",
			messageId: "msg-provenance-placeholder",
			modelUsed: "external-client",
		});

		await resolveWatcherRunsByMessageIds(["msg-provenance-placeholder"], {
			ok: true,
		});

		// Not 'external-client': the SERVER dispatched this run to its own agent.
		expect(await modelUsedOf(runId)).toBe("lobu-agent");
	});

	it("stamps a run that never had any model recorded", async () => {
		const { runId } = await createDispatchedRun({
			slug: "provenance-null",
			messageId: "msg-provenance-null",
			modelUsed: null,
		});

		await resolveWatcherRunsByMessageIds(["msg-provenance-null"], { ok: true });

		expect(await modelUsedOf(runId)).toBe("lobu-agent");
	});

	it("keeps a model the agent actually reported", async () => {
		const { runId } = await createDispatchedRun({
			slug: "provenance-reported",
			messageId: "msg-provenance-reported",
			modelUsed: "gemini-2.5-pro",
		});

		await resolveWatcherRunsByMessageIds(["msg-provenance-reported"], {
			ok: true,
		});

		// The placeholder is the only thing being replaced — a real report wins.
		expect(await modelUsedOf(runId)).toBe("gemini-2.5-pro");
	});

	it("does not invent an executor for a run that failed", async () => {
		const { runId } = await createDispatchedRun({
			slug: "provenance-failed",
			messageId: "msg-provenance-failed",
			modelUsed: "external-client",
		});

		await resolveWatcherRunsByMessageIds(["msg-provenance-failed"], {
			ok: false,
			error: "provider exploded",
		});

		// The failure path never reached the agent's completion, so the stamp
		// must not claim it did.
		expect(await modelUsedOf(runId)).toBe("external-client");
	});
});

#!/usr/bin/env bun

/**
 * API Response Renderer
 * Broadcasts worker responses to SSE connections for direct API clients
 */

import {
  AGENT_ERRORS,
  createLogger,
  type SuggestedPrompt,
  toAgentErrorCode,
} from "@lobu/core";
import { labelProviderErrorBody } from "../../utils/url-builder.js";
import type { ThreadResponsePayload } from "../infrastructure/queue/types.js";
import type { ResponseRenderer } from "../platform/response-renderer.js";
import type { SseManager } from "../services/sse-manager.js";
import { resolveWatcherRunsByMessageIds } from "../../watchers/run-completion.js";
import { readCurrentSuggestion } from "../suggestions/persist-suggestion.js";

const logger = createLogger("api-response-renderer");

/**
 * Response renderer for API platform
 * Broadcasts responses to SSE clients instead of external platforms
 */
export class ApiResponseRenderer implements ResponseRenderer {
  constructor(private readonly sseManager: SseManager) {}

  /**
   * The SSE session a payload broadcasts to. Clients subscribe on the
   * conversation id (GET /events keys connections by session.conversationId
   * — see routes/public/agent.ts).
   */
  private sessionIdFor(payload: ThreadResponsePayload): string | undefined {
    return payload.conversationId;
  }

  /**
   * Handle streaming delta content
   * Broadcasts delta to SSE connections
   */
  async handleDelta(
    payload: ThreadResponsePayload,
    _sessionKey: string
  ): Promise<string | null> {
    const sessionId = this.sessionIdFor(payload);

    if (!sessionId) {
      logger.warn("No session ID found in payload for delta broadcast");
      return null;
    }

    // Broadcast delta to SSE clients
    this.sseManager.broadcast(sessionId, "output", {
      type: "delta",
      content: payload.delta,
      timestamp: payload.timestamp || Date.now(),
      messageId: payload.messageId,
    });

    logger.debug(
      `Broadcast delta to session ${sessionId}: ${payload.delta?.length || 0} chars`
    );

    return payload.messageId;
  }

  /**
   * Handle completion of response processing
   * Sends completion event to SSE clients
   */
  async handleCompletion(
    payload: ThreadResponsePayload,
    _sessionKey: string
  ): Promise<void> {
    const sessionId = this.sessionIdFor(payload);

    if (!sessionId) {
      logger.warn("No session ID found in payload for completion broadcast");
      return;
    }

    // Resolve the current suggestion set for this conversation and decide
    // whether to attach it to `complete` (this turn produced it), clear it
    // (this turn produced none — stale chips must not linger), or leave it
    // untouched (turn errored — do not alter durable suggestion state). This
    // runs on the SSE-owning pod (terminal rows are owner-gated),
    // so embedding on `complete` — rather than a separate post-complete card
    // the SPA would miss after it closes the socket — is the only live path.
    const suggestions = await this.resolveTerminalSuggestions(payload);

    // Broadcast completion to SSE clients.
    //
    // Carry the worker's authoritative `finalText` (the full assistant reply,
    // added to the terminal row in gateway-integration.signalCompletion for
    // exactly this cross-replica reason). Streaming `output` deltas stay
    // best-effort under N>1: a delta row claimed on a non-owning pod is lost
    // (the SseManager is per-pod), so the SPA's accumulated text can be
    // truncated. The SPA repairs from `finalText` on this terminal event —
    // without it a cross-pod delta loss would leave a permanently truncated
    // message with no repair. (Empty string when nothing was streamed.)
    this.sseManager.broadcast(sessionId, "complete", {
      type: "complete",
      messageId: payload.messageId,
      processedMessageIds: payload.processedMessageIds,
      finalText: payload.finalText,
      suggestions,
      timestamp: payload.timestamp || Date.now(),
    });

    logger.info(`Broadcast completion to session ${sessionId}`);

    await this.resolveWatcherRunsFromPayload(payload, { ok: true });
  }

  /**
   * READ-ONLY: resolve the chips to embed on this turn's `complete` payload.
   * The durable set is already finalized before this runs — the consumer calls
   * `finalizeTurnSuggestions` at the terminal boundary (BEFORE the SSE
   * owner-gate), which supersedes a stale prior set or keeps this turn's own.
   * So the current row here is the authoritative post-turn state; this method
   * never mutates it, it only decides what the SPA renders:
   *  - errored turn → undefined ("no change").
   *  - a current set exists → return it (embed).
   *  - none current → [] ("clear"): finalize already superseded it.
   */
  private async resolveTerminalSuggestions(
    payload: ThreadResponsePayload
  ): Promise<SuggestedPrompt[] | undefined> {
    // Error delivery does not alter durable suggestion state.
    if (payload.error) return undefined;
    const organizationId =
      payload.organizationId ??
      (typeof payload.platformMetadata?.organizationId === "string"
        ? payload.platformMetadata.organizationId
        : undefined);
    if (!organizationId) return undefined;

    try {
      const current = await readCurrentSuggestion(
        organizationId,
        payload.conversationId
      );
      return current ? current.prompts : [];
    } catch (err) {
      // Never let suggestion resolution break completion delivery.
      logger.warn(
        `Failed to resolve terminal suggestions for ${payload.conversationId}: ${
          err instanceof Error ? err.message : String(err)
        }`
      );
      return undefined;
    }
  }

  /**
   * Handle error response
   * Sends error event to SSE clients
   */
  async handleError(
    payload: ThreadResponsePayload,
    _sessionKey: string
  ): Promise<void> {
    const sessionId = this.sessionIdFor(payload);

    if (!sessionId) {
      logger.warn("No session ID found in payload for error broadcast");
      return;
    }

    // This SSE surface forwards the context so the frontend can build the CTA,
    // but it lacks the org/agent ids needed to resolve the URL itself.
    const code = toAgentErrorCode(payload.errorCode);
    const spec = code ? AGENT_ERRORS[code] : undefined;
    if (spec?.silent) {
      // Silent codes (SESSION_TIMEOUT) are retried and must not surface.
      await this.resolveWatcherRunsFromPayload(payload, {
        ok: false,
        error: "agent error",
      });
      return;
    }
    const errorText =
      spec?.message ??
      labelProviderErrorBody(payload.error, payload.errorContext?.provider);

    const errorEvent = {
      type: "error",
      error: errorText,
      errorCode: code,
      errorContext: payload.errorContext,
      messageId: payload.messageId,
      timestamp: payload.timestamp || Date.now(),
    };

    // Keep the legacy `error` event for existing consumers, but also emit a
    // non-reserved event name for browsers: native EventSource treats `error`
    // specially and may not expose server-sent event data to addEventListener.
    this.sseManager.broadcast(sessionId, "error", errorEvent);
    this.sseManager.broadcast(sessionId, "agent-error", errorEvent);

    logger.error(`Broadcast error to session ${sessionId}: ${errorText}`);

    await this.resolveWatcherRunsFromPayload(payload, {
      ok: false,
      error: typeof errorText === "string" ? errorText : "agent error",
    });
  }

  /**
   * Resolve any watcher runs whose dispatched messageId matches the terminal
   * event. Checks both the immediate messageId and processedMessageIds since
   * a single turn can batch-process multiple messages. Durable and replica-
   * safe: keyed on runs.dispatched_message_id, idempotent via the active-
   * status guard, so it's correct on whichever replica claims the row.
   */
  private async resolveWatcherRunsFromPayload(
    payload: ThreadResponsePayload,
    result: { ok: true } | { ok: false; error: string }
  ): Promise<void> {
    const ids = new Set<string>();
    if (payload.messageId) ids.add(payload.messageId);
    for (const id of payload.processedMessageIds ?? []) {
      if (id) ids.add(id);
    }
    try {
      await resolveWatcherRunsByMessageIds(ids, result);
    } catch (error) {
      logger.error("Failed to resolve watcher runs from terminal API payload", {
        error,
      });
    }
  }

  /**
   * Handle status updates (heartbeat with elapsed time)
   * Sends status event to SSE clients
   */
  async handleStatusUpdate(payload: ThreadResponsePayload): Promise<void> {
    const sessionId = this.sessionIdFor(payload);

    if (!sessionId) {
      return;
    }

    // Broadcast status to SSE clients. `statusUpdate` is an object
    // ({ elapsedSeconds, state }); the SPA's SSE consumer expects `status` to be
    // a plain string and renders it verbatim (italicized). Sending the object
    // here makes the client coerce it via String(...) → "[object Object]".
    // Send the human-readable `state` ("is running", "is scheduling", …).
    this.sseManager.broadcast(sessionId, "status", {
      type: "status",
      status: payload.statusUpdate?.state ?? "Working",
      messageId: payload.messageId,
      timestamp: payload.timestamp || Date.now(),
    });
  }

  /**
   * Handle ephemeral messages
   * For API platform, these are just broadcast as regular events
   */
  async handleEphemeral(payload: ThreadResponsePayload): Promise<void> {
    const sessionId = this.sessionIdFor(payload);

    if (!sessionId) {
      return;
    }

    // Broadcast ephemeral content to SSE clients
    this.sseManager.broadcast(sessionId, "ephemeral", {
      type: "ephemeral",
      content: payload.content,
      messageId: payload.messageId,
      timestamp: payload.timestamp || Date.now(),
    });
  }

  /**
   * Stop stream for conversation - no-op for API platform
   * SSE connections handle their own lifecycle
   */
  async stopStreamForConversation(
    _userId: string,
    _conversationId: string
  ): Promise<void> {
    // No-op - SSE connections manage their own lifecycle
  }
}

