1	import type { DbClient } from "../db/client";
2	import { getDb, pgTextArray } from "../db/client";
3	import { listPendingToolsForRun } from "../gateway/auth/mcp/pending-tool-store";
4	import logger from "../utils/logger";
5	import { ACTIVE_RUN_STATUSES, runStatusLiteral } from "../utils/run-statuses";
6	import { advanceScheduleAfterTerminalFailure } from "./schedule-cursor";
7	
8	type WatcherTerminalResult = { ok: true } | { ok: false; error: string };
9	
10	/**
11	 * How many times a watcher run that finished its agent turn WITHOUT calling
12	 * `complete_window` is re-dispatched before being marked failed. The agent
13	 * read its inputs and replied but skipped the finalize tool call — a soft,
14	 * usually-non-deterministic miss (the model "forgot" the closing step). A
15	 * bounded re-dispatch gives it a fresh turn to finalize. Default 1 (one extra
16	 * attempt); 0 disables. Each re-dispatch is a full agent turn, so keep it low.
17	 *
18	 * NOTE: this is a re-dispatch (a fresh session via the existing dispatch loop),
19	 * not a warm in-session nudge — the agent-worker is platform-agnostic and has
20	 * no notion of watchers/complete_window, so a worker-side self-nudge would
21	 * break that isolation. This constant is the GLOBAL default; a watcher can
22	 * override it via execution_config.finalize_nudges (see
23	 * resolveFinalizeNudgeBudget). A declarative defineBehavior surface for it is
24	 * the remaining follow-up (the CLI doesn't expose execution_config yet).
25	 */
26	const MAX_FINALIZE_NUDGES: number = (() => {
27		const raw = process.env.LOBU_WATCHER_FINALIZE_NUDGES;
28		if (raw === undefined) return 1;
29		const n = Number(raw);
30		return Number.isFinite(n) && n >= 0 ? Math.floor(n) : 1;
31	})();
32	
33	/**
34	 * Finalize-nudge budget for a run: the watcher's per-watcher override
35	 * (execution_config.finalize_nudges, 0-5) when set, else the global default.
36	 * Clamped defensively in case a raw DB value sits outside the schema's range.
37	 */
38	function resolveFinalizeNudgeBudget(
39		executionConfig: Record<string, unknown> | null | undefined
40	): number {
41		const override = executionConfig?.finalize_nudges;
42		if (typeof override === "number" && Number.isFinite(override)) {
43			return Math.min(5, Math.max(0, Math.floor(override)));
44		}
45		return MAX_FINALIZE_NUDGES;
46	}
47	
48	export async function findWindowIdForRun(
49		sql: DbClient,
50		runId: number
51	): Promise<number | null> {
52		// Canvas-on-events: a run produced a window iff a canvas chain member carries
53		// this run_id (stamped atomically inside complete_window's tx). A fresh
54		// completion stamps the ROOT; a replace_existing completion stamps the
55		// superseding HEAD — so match ANY member and resolve the window identity via
56		// metadata.root_event_id (a root omits it → its own id). Scoped to
57		// canvas_state so it never matches tab_event/tab_snapshot BROWSER rows that
58		// also carry run_id.
59		const rows = await sql`
60	    SELECT COALESCE((metadata->>'root_event_id')::bigint, id) AS id
61	    FROM events
62	    WHERE run_id = ${runId}
63	      AND semantic_type = 'canvas_state'
64	    ORDER BY id DESC
65	    LIMIT 1
66	  `;
67	
68		return rows.length > 0 ? Number((rows[0] as { id: unknown }).id) : null;
69	}
70	
71	/**
72	 * Mark a Behavior run completed, recording who executed it when the caller
73	 * knows.
74	 *
75	 * `complete_window` used to default `runs.model_used` to the literal
76	 * 'external-client' whenever its caller omitted `model`, and the platform's own
77	 * Lobu agent omits it — so server-dispatched runs were labelled as though an
78	 * outside MCP client had executed them. That label reads as an observation and
79	 * is not one: triaging the July 2026 Behavior collapse from this column
80	 * produced exactly that wrong conclusion.
81	 *
82	 * `fallbackModel` is the caller's assertion about the executor and is applied
83	 * ONLY over the placeholder or a NULL — a model the agent genuinely reported
84	 * always wins. Callers that cannot prove who executed the run must omit it
85	 * rather than guess: `reconcileWatcherRuns` sweeps active runs without
86	 * filtering on `dispatched_message_id`, so it can reach runs an external client
87	 * created, and stamping those would invert the very bug this fixes.
88	 *
89	 * (SQL comments are kept out of the template literal: a backtick inside one
90	 * terminates the string and fails the esbuild transform, not just at runtime.)
91	 */
92	export async function markWatcherRunCompleted(
93		sql: DbClient,
94		runId: number,
95		windowId: number | null,
96		fallbackModel?: string
97	): Promise<void> {
98		await sql`
99	    UPDATE runs
100	    SET status = 'completed',
101	        window_id = ${windowId},
102	        completed_at = current_timestamp,
103	        error_message = NULL,
104	        model_used = COALESCE(
105	          ${fallbackModel ?? null},
106	          model_used
107	        )
108	    WHERE id = ${runId}
109	      AND status = ANY(${runStatusLiteral(ACTIVE_RUN_STATUSES)}::text[])
110	  `;
111	}
112	
113	async function markWatcherRunFailed(
114		sql: DbClient,
115		runId: number,
116		message: string
117	): Promise<boolean> {
118		return sql.begin(async (tx) => {
119			const [failed] = await tx<{
120				watcher_id: string | number | null;
121				dispatch_source: string | null;
122			}>`
123	      UPDATE runs
124	      SET status = 'failed',
125	          completed_at = current_timestamp,
126	          error_message = ${message}
127	      WHERE id = ${runId}
128	        AND status = ANY(${runStatusLiteral(ACTIVE_RUN_STATUSES)}::text[])
129	      RETURNING watcher_id, approved_input->>'dispatch_source' AS dispatch_source
130	    `;
131			if (!failed) return false;
132			await advanceScheduleAfterTerminalFailure(
133				tx,
134				failed.watcher_id == null ? null : Number(failed.watcher_id),
135				failed.dispatch_source
136			);
137			return true;
138		});
139	}
140	
